import{z as i,x as l,o as t,c as p,q as r,j as e,D as E,d as o,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Barro 税收平滑","description":"","frontmatter":{"title":"Barro 税收平滑","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/tax-smoothing-barro.md","filePath":"econ/tax-smoothing-barro.md","lastUpdated":1791413859000}'),A={name:"econ/tax-smoothing-barro.md"};function d(u,a,h,m,_,c){const B=l("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="barro-税收平滑" tabindex="-1">Barro 税收平滑 <a class="header-anchor" href="#barro-税收平滑" aria-label="Permalink to &quot;Barro 税收平滑&quot;">​</a></h1><div class="epigraph"><p>扭曲税的边际成本应像永久收入那样平滑；暂时的支出用发债摊开，税率跟着永久支出走，而不是每年把预算轧平。</p><footer>—— Barro, On the Determination of the Public Debt, JPE 1979</footer></div><p><a href="/econ/fiscal-multiplier">上一课</a>在李嘉图与名义刚性下给出 \\(G\\) 与减税的乘数，并声明一次总付税债互换可以不改 \\(C\\)。本课的缺口是换税种：若税是扭曲的（劳动、消费税），时间路径本身有成本，最优不是每期平衡预算，而是平滑税率。Barro（1979）把公共债务写成税收平滑的缓冲。物价水平的财政理论下一课才问名义锚是否由盈余现值定；本课先在实际量上写债务。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>乘数课的李嘉图用一次总付税：税的<strong>时机</strong>不扭曲，只有现值进财富。劳动税、销售税使边际决策变形，凸的超额负担意味着税率波动本身有成本——与消费的永久收入同构。缺口是：给定支出路径 \\(\\{G_t\\}\\)（含战争等暂时高峰），如何选 \\(\\{ \\tau_t\\}\\) 与债务。Barro：近似随机游走的税率，\\(\\tau_t\\approx\\mathbb{E}_t\\tau_{t+1}\\)，暂时 \\(G\\) 用赤字，永久 \\(G\\) 用永久更高的 \\(\\tau\\)。这与「每年平衡预算」或「金规则只为资本项目发债」都不同。</p><p><span class="marginnote">税收平滑的直觉类比：像还房贷选等额本息——每年还差不多的数目，比头一年咬牙还掉一半、之后两手空空轻松得多。政府同理：与其在战争年份把税率拉到顶、和平年份归零，不如让税率停在一条平线上，用国债把高峰支出摊到几十年里慢慢收。</span></p><p><span class="marginnote">平滑的是税率（边际扭曲），不是税收收入。税基随 \\(Y\\) 变时，收入可以波动，税率仍平。自动稳定器再下一课才把税基弹性当宏观缓冲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计划者最小化扭曲的现值，约束是政府跨期预算（不含一次总付）。一阶条件使相邻期边际扭曲的贴现值对齐，故 \\(\\tau\\) 近随机游走。债务是状态：吸收 \\(G\\) 与税基的暂时冲击。预期到的永久战争：\\(\\tau\\) 立刻跳到新的永久水平，以免未来再跳。这与家庭 PIH 同构，对象是税。Ramsey 商品税（Ramsey 课）给出税种结构；本课只谈<strong>同一税种的时间平滑</strong>。</p>',9)),(t(),e(s,null,{default:E(()=>[n(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%94%AF%E5%87%BA%E8%B7%AF%E5%BE%84%20G%22%5D%20--%3E%20SMOOTH%5B%22%E7%A8%8E%E7%8E%87%E5%B9%B3%E6%BB%91%22%5D%0A%20%20SMOOTH%20--%3E%20TAU%5B%22%CF%84%20%E2%89%88%20E%CF%84%E2%80%B2%22%5D%0A%20%20TEMP%5B%22%E6%9A%82%E6%97%B6%20G%22%5D%20--%3E%20DEBT%5B%22%E5%80%BA%E5%8A%A1%E7%BC%93%E5%86%B2%22%5D%0A%20%20PERM%5B%22%E6%B0%B8%E4%B9%85%20G%22%5D%20--%3E%20JUMP%5B%22%CF%84%20%E7%AB%8B%E5%88%BB%E4%B8%8A%E7%A7%BB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>李嘉图在扭曲税下部分破裂：税的时机改变劳动供给与消费的跨期价格，乘数与平滑同时存在。下限上若要用 \\(G\\) 刺激，平滑仍要求事后用债务摊还，而不是立刻用扭曲税轧平把刺激抵消掉——与乘数课的规则依赖一致。</p><h3 id="不是为发债而发债" tabindex="-1">不是为发债而发债 <a class="header-anchor" href="#不是为发债而发债" aria-label="Permalink to &quot;不是为发债而发债&quot;">​</a></h3><p>平滑给出债务的<strong>规范</strong>用途：保险税基与摊平暂时支出。它不给债务水平一个与 \\(\\pi\\) 无关的上限故事，也不等于 FTPL。不可持续的债务路径会在下一课变成价格水平跳跃或违约。本课假设政府仍满足现值约束。</p><h3 id="平滑不是周期乘数菜单" tabindex="-1">平滑不是周期乘数菜单 <a class="header-anchor" href="#平滑不是周期乘数菜单" aria-label="Permalink to &quot;平滑不是周期乘数菜单&quot;">​</a></h3><p>暂时 \\(G\\) 用债，是为了不让 \\(\\tau\\) 的平方超额负担集中爆发。它不回答 \\(G\\) 本身该不该在下限上加大——那是乘数课的规则依赖。</p><p>两句话要一起读：刺激可以暂时抬 \\(G\\)，融资应平滑 \\(\\tau\\)，而不是当年加扭曲税把刺激对冲掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>战争或灾难使 \\(G\\) 暂时升高：若立刻用高 \\(\\tau\\) 融资，超额负担以税率的平方上升。发债把 \\(\\tau\\) 的升幅摊到未来多期，每期扭曲更小，现值更低。和平后盈余还债，\\(\\tau\\) 不必低于平滑路径去「还清」得过快。资本税的时间不一致（承诺课）会破坏这条平滑：将来的自己想抽资本存量的一次性税。Barro 的随机游走默认承诺能维持。</p>',8)),(t(),e(s,null,{default:E(()=>[n(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAR%5B%22%E6%88%98%E4%BA%89%EF%BC%9AG%20%E6%9A%82%E6%97%B6%E7%BF%BB%E5%80%8D%22%5D%20--%3E%20S1%5B%22%E6%96%B9%E6%A1%88%E4%B8%80%EF%BC%9A%E5%BD%93%E5%B9%B4%E5%8A%A0%E7%A8%8E%E8%BD%A7%E5%B9%B3%22%5D%0A%20%20WAR%20--%3E%20S2%5B%22%E6%96%B9%E6%A1%88%E4%BA%8C%EF%BC%9A%E5%8F%91%E5%80%BA%EF%BC%8C%E7%A8%8E%E7%8E%87%E5%B0%8F%E5%B9%85%E4%B8%8A%E5%8D%87%E6%91%8A%E5%88%B0%E5%A4%9A%E5%B9%B4%22%5D%0A%20%20S1%20--%3E%20EB1%5B%22%CF%84%20%E9%A3%99%E5%8D%87%EF%BC%8C%E8%B6%85%E9%A2%9D%E8%B4%9F%E6%8B%85%E6%8C%89%20%CF%84%C2%B2%20%E9%9B%86%E4%B8%AD%E7%88%86%E5%8F%91%22%5D%0A%20%20S2%20--%3E%20EB2%5B%22%E6%AF%8F%E6%9C%9F%E6%89%AD%E6%9B%B2%E9%83%BD%E8%A2%AB%E5%8E%8B%E5%B9%B3%EF%BC%8C%E6%80%BB%E6%89%AD%E6%9B%B2%E7%8E%B0%E5%80%BC%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20S2%20--%3E%20REP%5B%22%E5%92%8C%E5%B9%B3%E5%90%8E%E7%9B%88%E4%BD%99%E9%80%90%E6%AD%A5%E8%BF%98%E5%80%BA%22%5D%0A%20%20EB1%20--%3E%20CMP%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E6%94%AF%E5%87%BA%EF%BC%8C%E6%80%BB%E6%89%AD%E6%9B%B2%E6%88%90%E6%9C%AC%E6%9B%B4%E9%AB%98%22%5D%0A%20%20EB2%20--%3E%20CMP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">数字实例：超额负担近似与税率的平方成正比。设两年要筹同样的钱：方案一第一年税率 40%、第二年 20%，扭曲成本 \\(40^2+20^2=2000\\)；方案二两年都 30%，\\(30^2+30^2=1800\\)。税率没多收一分钱，平一平就省下 10% 的扭曲——「平方」就是平滑的全部秘密。</span></p><p>乘数课的一次总付减税不改变扭曲路径；本课的减税若降低 \\(\\tau\\)，必须用未来 \\(\\tau\\) 或支出补上现值，否则不是平滑而是改永久税率。把刺激性减税写成税收平滑，会把周期政策与 Ramsey 时间路径焊成一句。平滑允许周期中税基波动造成的赤字，不允许把永久支出当成暂时来发债。</p><p>开放经济下，债务可以卖给外国人，\\(S-I\\) 与 FH 相关再进来；平滑仍是税率逻辑。CIP 不决定 \\(\\tau\\) 路径，实证见 <code>/quant/irp</code>。</p><p><span class="marginnote">通胀税是另一种扭曲税。未预期通胀可以降低实际债，像一次性资本税，破坏平滑与承诺。本课的 \\(\\tau\\) 先指明文税率。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计最优债务/GDP，不把平滑写成「可以无限赤字」。FTPL 下一课：若盈余现值钉不住， \\(P\\) 会跳。自动稳定器把 \\(\\tau\\) 规则写成周期函数，与平滑的「税率不随暂时 \\(Y\\) 动」在字面上紧张——稳定器平滑的是私人收入，税率表可以累进；Barro 平滑的是边际税率的随机游走。声明对象，不要焊死。</p><p>战争之外，衰退中的暂时 \\(G\\) 或暂时低税基，平滑同样指向赤字，而不是立刻加税把乘数课的刺激抵消。永久的老龄化支出必须进永久 \\(\\tau\\)，不能靠滚动债务假装暂时。这是会计上的永久/暂时分解，不是政治上的「以后再调」。李嘉图一次总付下时机无成本；本课一旦引入扭曲，时机就是福利对象。</p><p><span class="marginnote">常见误区：初学者容易把「暂时支出可以发债」读成「永远都可以发债」。平滑的前提是现值约束：暂时支出结束后，盈余要真拿去还债。把老龄化这类<strong>永久</strong>支出也包装成「暂时」去发债，就不是平滑，而是滚雪球——总有一天以通胀跳跃或违约收场（下一课 FTPL）。</span></p><p>后课默认：扭曲税下债务是平滑缓冲，税率近随机游走；一次总付李嘉图不再是唯一基准。下一课：名义债务与物价水平是否由财政现值决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>乘数课用一次总付；本课用扭曲税的时间路径。</li><li>Barro：\\(\\tau\\) 近随机游走，暂时 \\(G\\) 用债，永久 \\(G\\) 用永久 \\(\\tau\\)。</li><li>平滑的是边际扭曲，不是每期预算平衡。</li><li>现值约束仍要满足；FTPL 是下一课的名义接头。</li><li>出处：Barro, <em>JPE</em> 1979。</li></ul>',11))])}const P=i(A,[["render",d]]);export{D as __pageData,P as default};
